		symbolsPerRow.remove(symbolsPerRow.size() - 1);
	}

	Map<Character, Integer> totals = calculateTotals(symbolsPerRow);

	Map<Character, Integer> sums = new HashMap<Character, Integer>();
	Set<Character> toRemove = new HashSet<Character>();

